package com.productionhouse.crm.legal.rights.service;
import com.productionhouse.crm.auth.api.ApiException;import com.productionhouse.crm.legal.contracts.entity.ContractRecord;import com.productionhouse.crm.legal.contracts.repository.ContractRecordRepository;import com.productionhouse.crm.legal.rights.dto.*;import com.productionhouse.crm.legal.rights.entity.ContentRight;import com.productionhouse.crm.legal.rights.repository.ContentRightRepository;import com.productionhouse.crm.mediahouse.media.entity.MediaAsset;import com.productionhouse.crm.mediahouse.media.repository.MediaAssetRepository;import com.productionhouse.crm.task5.util.Task5Paging;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDate;import java.util.*;
@Service public class ContentRightService{
private final ContentRightRepository repo;private final MediaAssetRepository media;private final ContractRecordRepository contracts;public ContentRightService(ContentRightRepository repo,MediaAssetRepository media,ContractRecordRepository contracts){this.repo=repo;this.media=media;this.contracts=contracts;}
@Transactional(readOnly=true) public Page<ContentRightResponse> list(String q,String status,String projectRef,Long mediaId,String territory,String platform,LocalDate expiresBefore,Integer expiresWithinDays,int page,int size,String sort,String direction){if(expiresWithinDays!=null&&(expiresWithinDays<0||expiresWithinDays>3650))throw ApiException.badRequest("expiresWithinDays must be between 0 and 3650.");LocalDate today=LocalDate.now();LocalDate soon=expiresWithinDays==null?null:today.plusDays(expiresWithinDays);String field=Set.of("name","status","createdAt","updatedAt","startsAt","endsAt").contains(sort)?sort:"createdAt";Sort order=Sort.by("asc".equalsIgnoreCase(direction)?Sort.Direction.ASC:Sort.Direction.DESC,field);return Task5Paging.page(repo.findAll(order).stream().filter(e->blank(q)||contains(e.getName(),q)).filter(e->blank(status)||status.equalsIgnoreCase(effectiveStatus(e,today))).filter(e->blank(projectRef)||projectRef.equals(e.getProjectRef())).filter(e->mediaId==null||e.getMediaAsset()!=null&&mediaId.equals(e.getMediaAsset().getId())).filter(e->blank(territory)||territory.equalsIgnoreCase(e.getTerritory())).filter(e->blank(platform)||e.getPlatforms()!=null&&Arrays.stream(e.getPlatforms().split(",")).anyMatch(p->p.trim().equalsIgnoreCase(platform.trim()))).filter(e->expiresBefore==null||e.getEndsAt()!=null&&!e.getEndsAt().isAfter(expiresBefore)).filter(e->soon==null||e.getEndsAt()!=null&&!e.getEndsAt().isBefore(today)&&!e.getEndsAt().isAfter(soon)).map(this::response).toList(),page,size);}
@Transactional(readOnly=true) public ContentRightResponse get(Long id){return response(find(id));}
@Transactional public ContentRightResponse create(ContentRightRequest r){return response(save(new ContentRight(),r));}
@Transactional public ContentRightResponse update(Long id,ContentRightRequest r){return response(save(find(id),r));}
@Transactional public void delete(Long id){repo.delete(find(id));}
private ContentRight find(Long id){return repo.findById(id).orElseThrow(()->ApiException.notFound("Content right not found."));}
private ContentRight save(ContentRight e,ContentRightRequest r){if(r.endsAt().isBefore(r.startsAt()))throw ApiException.badRequest("endsAt must be on or after startsAt.");String status=r.status().trim().toUpperCase(Locale.ROOT);if(!Set.of("DRAFT","ACTIVE","EXPIRED","TERMINATED").contains(status))throw ApiException.badRequest("Unsupported rights status.");MediaAsset asset=media.findById(r.mediaId()).orElseThrow(()->ApiException.badRequest("Referenced media asset does not exist."));ContractRecord contract=r.contractId()==null?null:contracts.findById(r.contractId()).orElseThrow(()->ApiException.badRequest("Referenced contract does not exist."));if(contract!=null){if(contract.getMediaAsset()!=null&&!contract.getMediaAsset().getId().equals(asset.getId()))throw ApiException.badRequest("The selected contract is associated with a different media asset.");if(contract.getStartsAt()!=null&&r.startsAt().isBefore(contract.getStartsAt()))throw ApiException.badRequest("Rights cannot start before the associated contract.");if(contract.getEndsAt()!=null&&r.endsAt().isAfter(contract.getEndsAt()))throw ApiException.badRequest("Rights cannot outlast the associated contract.");if("ACTIVE".equals(status)&&(!"ACTIVE".equals(contract.getStatus())||contract.getEndsAt()!=null&&contract.getEndsAt().isBefore(LocalDate.now())))throw ApiException.badRequest("Active rights require an active, unexpired contract.");}e.setName(r.name().trim());e.setDescription(clean(r.description()));e.setProjectRef(clean(r.projectRef()));e.setRightsType(r.rightsType().trim());e.setMediaAsset(asset);e.setContract(contract);e.setTerritory(r.territory().trim());e.setPlatforms(r.platforms().trim());e.setLanguages(clean(r.languages()));e.setExclusive(r.exclusive());e.setStartsAt(r.startsAt());e.setEndsAt(r.endsAt());e.setRestrictions(clean(r.restrictions()));e.setStatus(status);e.setActive(r.active()==null||r.active());return repo.save(e);}
private String effectiveStatus(ContentRight e,LocalDate today){return "ACTIVE".equals(e.getStatus())&&e.getEndsAt()!=null&&e.getEndsAt().isBefore(today)?"EXPIRED":e.getStatus();}
private ContentRightResponse response(ContentRight e){return new ContentRightResponse(e.getId(),e.getName(),e.getDescription(),e.getProjectRef(),e.getRightsType(),e.getMediaAsset()==null?null:e.getMediaAsset().getId(),e.getContract()==null?null:e.getContract().getId(),e.getTerritory(),e.getPlatforms(),e.getLanguages(),e.isExclusive(),e.getStartsAt(),e.getEndsAt(),e.getRestrictions(),effectiveStatus(e,LocalDate.now()),e.isActive(),e.getCreatedAt(),e.getUpdatedAt());}
private boolean blank(String x){return x==null||x.isBlank();}private boolean contains(String x,String q){return x!=null&&x.toLowerCase(Locale.ROOT).contains(q.trim().toLowerCase(Locale.ROOT));}private String clean(String x){return x==null||x.isBlank()?null:x.trim();}}

